"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[4788],{4788(e,t,n){n.d(t,{content:()=>o,description:()=>r,keywords:()=>a,title:()=>i});n(5043);var s=n(579);const i="The Critics Are Right: Most EdTech Is Useless",r="US schools spent $30 billion on edtech in 2024. Critics say it's wasted. They're right about passive screen time. But virtual labs that make students actually DO science? That's a different story.",a=["edtech effectiveness","virtual labs learning outcomes","active learning technology","education technology criticism","passive vs active learning","OECD digital education","AI in education"],o=(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)("p",{children:[(0,s.jsx)("em",{children:'"Is education technology mostly useless?"'})," asks"," ",(0,s.jsx)("a",{href:"https://www.economist.com/letters/2026/02/12/is-education-technology-mostly-useless",target:"_blank",rel:"noopener noreferrer",children:"The Economist"}),". ",(0,s.jsx)("em",{children:'"Kids Spend Hours in School on Screens. And for What?"'})," echoes"," ",(0,s.jsx)("a",{href:"https://www.bloomberg.com/opinion/articles/2026-02-11/education-technology-isn-t-teaching-us-children-more-effectively",target:"_blank",rel:"noopener noreferrer",children:"Bloomberg"}),". These are damning headlines. And as an edtech company ourselves, we find ourselves agreeing with much of the criticism."]}),(0,s.jsxs)("p",{children:["The Bloomberg piece highlights a staggering figure: US schools spent ",(0,s.jsx)("strong",{children:"$30 billion on education technology in 2024"}),", ten times what they spent on textbooks. Where did that investment go? Mostly into tablets, laptops, learning management systems, and apps that promised engagement but often delivered little more than screen time. The return on investment, according to these critics, has been questionable at best."]}),(0,s.jsx)("h2",{children:"Why Is Most EdTech Failing?"}),(0,s.jsxs)("p",{children:["The critics aren't wrong. They're just not specific enough about the problem. The issue isn't technology in education. The issue is ",(0,s.jsx)("strong",{children:"passive technology"})," in education."]}),(0,s.jsxs)("p",{children:['Consider what most "edtech" actually looks like in practice: students watching videos, clicking through multiple-choice quizzes, scrolling through digital textbooks. This is the same passive consumption that happens with television, just dressed up in educational language. The screen does the work while the student sits passively. Research consistently shows that passive learning has limited effectiveness compared to active engagement (',(0,s.jsx)("a",{href:"https://www.pnas.org/doi/10.1073/pnas.1319030111",target:"_blank",rel:"noopener noreferrer",children:"Freeman et al., 2014"}),")."]}),(0,s.jsxs)("p",{children:["The"," ",(0,s.jsx)("a",{href:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html",target:"_blank",rel:"noopener noreferrer",children:"OECD's Digital Education Outlook 2026"})," ","makes this distinction clear. When general-purpose AI tools are simply handed to students without structure, learning often ",(0,s.jsx)("em",{children:"decreases"})," because students outsource their thinking to the machine. However, AI designed with ",(0,s.jsx)("strong",{children:'"intentional pedagogical purpose"'})," shows sustained improvements. The difference isn't whether technology is present. It's whether the technology requires the learner to actively engage."]}),(0,s.jsxs)("p",{children:["CoSN's"," ",(0,s.jsx)("a",{href:"https://www.eschoolnews.com/innovative-teaching/2026/02/16/new-cosn-report-underscores-importance-of-intentional-reliable-edtech-use/",target:"_blank",rel:"noopener noreferrer",children:"2026 Driving K-12 Innovation Report"})," ","reinforces this point: ",(0,s.jsx)("em",{children:'"without a human-centered strategy, even the best technology will fail."'})," Many schools purchased the technology without purchasing the strategy to implement it effectively."]}),(0,s.jsx)("h2",{children:"What Makes Active Learning Different?"}),(0,s.jsxs)("p",{children:["There is a substantial body of research on ",(0,s.jsx)("strong",{children:"active learning"}),", demonstrating that students learn more effectively when they do things rather than watch things. A landmark meta-analysis of 225 studies found that active learning improved examination performance by half a letter grade and reduced failure rates by 55% compared to traditional lecturing (",(0,s.jsx)("a",{href:"https://www.pnas.org/doi/10.1073/pnas.1319030111",target:"_blank",rel:"noopener noreferrer",children:"Freeman et al., 2014"}),"). The question for educators has always been: how do you create active learning experiences at scale?"]}),(0,s.jsx)("p",{children:"Physical science labs have always exemplified active learning. Students don't watch a titration; they perform one. They don't read about pendulum motion; they measure it. The learning happens through action, through trial and error, through the physical engagement of manipulating equipment and observing results firsthand."}),(0,s.jsxs)("p",{children:["The challenge is that physical labs are expensive, require careful safety management, are constrained by timetabling, and increasingly difficult to staff given the ongoing STEM teacher shortage. When COVID-19 closed schools worldwide, millions of students lost access to practical science education entirely (",(0,s.jsx)("a",{href:"https://www.iza.org/publications/dp/13820/covid-19-and-educational-inequality-how-school-closures-affect-low-and-high-achieving-students",target:"_blank",rel:"noopener noreferrer",children:"Grewenig et al., 2021"}),")."]}),(0,s.jsxs)("p",{children:["This is where most edtech solutions have failed. They replaced active physical labs with passive digital alternatives: animations of experiments, videos of scientists at work, clickable diagrams with labels. Students watch someone else do science instead of doing it themselves. These alternatives are cheaper and safer, but according to research on embodied cognition and motor learning, they miss the fundamental mechanism through which practical skills are acquired (",(0,s.jsx)("a",{href:"https://www.frontiersin.org/articles/10.3389/fpsyg.2019.00625/full",target:"_blank",rel:"noopener noreferrer",children:"Macedonia, 2019"}),")."]}),(0,s.jsx)("h2",{children:"How Can Virtual Labs Preserve Active Learning?"}),(0,s.jsxs)("p",{children:["At WhimsyLabs, we built our platform around one principle: preserve the ",(0,s.jsx)("em",{children:"active"}),' part of laboratory learning. In our virtual labs, students don\'t click a button labelled "add chemical." They physically pour liquids using natural hand movements. They don\'t select "heat beaker" from a menu. They position equipment over a Bunsen burner and control the flame themselves. They don\'t read about pipette technique. They develop muscle memory by actually pipetting, with their movements tracked and coached in real time.']}),(0,s.jsxs)("p",{children:["This approach is grounded in motor learning research. When you perform a physical action, your brain encodes it differently than when you watch someone else perform the same action. The neural pathways activated are different, the retention is different, and critically, the transfer to real-world skills is different (",(0,s.jsx)("a",{href:"https://www.nature.com/articles/nphys293",target:"_blank",rel:"noopener noreferrer",children:"Wieman & Perkins, 2006"}),")."]}),(0,s.jsx)("p",{children:'Our sandbox approach extends this further. Rather than following predetermined recipes, students design their own experiments. Given a problem such as "determine the concentration of this unknown acid," they must select appropriate equipment, plan their procedure, execute the techniques, analyse their results, and iterate when things don\'t work as expected. This is what scientists actually do. It requires active engagement at every step.'}),(0,s.jsx)("h2",{children:"Can AI Assessment Be Meaningful Rather Than Threatening?"}),(0,s.jsx)("p",{children:"The current concern about students using ChatGPT and similar tools to complete assignments is legitimate. Students can use AI to write essays, solve mathematics problems, and generate laboratory reports. Traditional assessment methods that focus on written outputs are increasingly vulnerable to this kind of circumvention."}),(0,s.jsxs)("p",{children:["However, there is something that text-generating AI fundamentally cannot do: ",(0,s.jsx)("strong",{children:"physically perform a procedure"}),"."]}),(0,s.jsxs)("p",{children:["Our AI tutor, WhimsyCat, observes ",(0,s.jsx)("em",{children:"how"})," students work, not just what written answers they produce. Did they hold the pipette at the correct angle? Did they approach the endpoint of a titration slowly enough? Did they remember to rinse the burette before filling it? Did they read the meniscus at eye level? These are physical actions captured in real time. They cannot be outsourced to a text generator because they are not text. They are motion, timing, spatial reasoning, and procedural knowledge demonstrated through action."]}),(0,s.jsxs)("p",{children:["Pearson's recent research on assessment has identified practical skills as inherently ",(0,s.jsx)("strong",{children:"AI-resistant"}),", not because anyone is deliberately blocking AI, but because the skills themselves require physical demonstration that language models cannot provide. You cannot fake titration technique by prompting ChatGPT. You have to actually do it."]}),(0,s.jsx)("p",{children:"WhimsyCat assesses students on their process: experimental design choices, technique quality, troubleshooting approaches, and safety awareness. Every assessment generates an audit trail that teachers can review. This is not AI replacing teacher judgement. It is AI providing detailed evidence that teachers can use to make better-informed judgements about student competence."}),(0,s.jsx)("h2",{children:"What Does Human-Centered EdTech Actually Look Like?"}),(0,s.jsxs)("p",{children:["The CoSN report emphasises that successful educational technology requires a ",(0,s.jsx)("em",{children:'"human-centered strategy."'})," We take this principle seriously. WhimsyLabs is not designed to replace science teachers. It is designed to support them in managing an increasingly impossible workload."]}),(0,s.jsx)("p",{children:"Consider the practical reality: a single science teacher supervising 30 students during a laboratory session cannot possibly observe each student's technique with the attention it deserves. There are not enough eyes, not enough time, not enough bandwidth. Consequently, practical assessment often becomes a checkbox exercise focused on whether students produced the expected final answer rather than whether they demonstrated competent technique."}),(0,s.jsx)("p",{children:"WhimsyCat provides continuous formative feedback while students work, coaching technique, identifying errors, and asking probing questions. This does not replace the teacher. It multiplies them. The teacher can focus attention on students who need human support while WhimsyCat handles routine guidance for others."}),(0,s.jsx)("p",{children:"Importantly, teachers remain in control. They can create custom experiments aligned with their curriculum. They can adjust difficulty levels. They can review AI assessments and override them when they disagree. The human remains at the centre of the educational process. The AI supports from the periphery."}),(0,s.jsx)("h2",{children:"What Questions Should We Be Asking About EdTech?"}),(0,s.jsx)("p",{children:"We would welcome more precise criticism of educational technology. Rather than asking broadly whether edtech is useless, consider these more specific questions:"}),(0,s.jsxs)("ul",{children:[(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:"Does this technology require active engagement?"})," If students can use it while half-attending, it is likely passive."]}),(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:"Does it assess process or only outcomes?"})," Multiple-choice quizzes capture only final answers. They miss the reasoning and technique that matters most."]}),(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:"Does it support teachers or attempt to replace them?"})," Teacher replacement has failed repeatedly. Teacher augmentation shows genuine promise."]}),(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:"Is there evidence of learning transfer?"})," Do students who use this technology perform better in real-world contexts?"]}),(0,s.jsxs)("li",{children:[(0,s.jsx)("strong",{children:"Was it designed with pedagogical intent?"})," Or was it designed by engineers who assumed learning would happen automatically once the technology was deployed?"]})]}),(0,s.jsx)("p",{children:"Much of the $30 billion spent on educational technology fails these tests. Tablets distributed without implementation plans fail these tests. Learning management systems that become repositories for PDF worksheets fail these tests. AI chatbots deployed without pedagogical frameworks fail these tests."}),(0,s.jsx)("p",{children:"Virtual laboratories where students physically perform experiments, receive real-time coaching on their technique, and demonstrate skills that AI cannot replicate? That represents a fundamentally different category of educational technology."}),(0,s.jsx)("h2",{children:"What Evidence Supports This Approach?"}),(0,s.jsxs)("p",{children:["We do not ask anyone to accept these claims on faith. At BETT 2025, students themselves voted for WhimsyLabs in the ",(0,s.jsx)("strong",{children:"Kids' Choice Awards"}),", recognising the platform for making science engaging and accessible. At BETT 2026, ",(0,s.jsx)("strong",{children:"Tech & Learning named us Best of BETT"}),". These are not marketing awards. They represent recognition from educators and students who actually used the product and found it valuable."]}),(0,s.jsx)("p",{children:"We are conducting ongoing research with partner schools measuring practical skill transfer. Early results indicate that students who practice procedures in WhimsyLabs demonstrate improved technique when they subsequently work in physical laboratories. The virtual practice transfers to real-world performance. The sandbox approach develops experimental design thinking that traditional cookbook-style labs struggle to cultivate."}),(0,s.jsx)("p",{children:"The critics are right: most edtech is failing to deliver meaningful educational value. We are working to be part of the solution rather than part of the problem."}),(0,s.jsx)("h2",{children:"Where Does This Leave Us?"}),(0,s.jsxs)("p",{children:['The debate about educational technology should not be framed as "technology versus no technology." That choice is no longer available. Technology is embedded in education and will remain so. The productive debate concerns ',(0,s.jsx)("em",{children:"what kind"})," of technology, designed according to ",(0,s.jsx)("em",{children:"what principles"}),", implemented with ",(0,s.jsx)("em",{children:"what strategies"}),"."]}),(0,s.jsx)("p",{children:"Passive screen time dressed up as learning? The critics are right to call it out. AI tools that do students' thinking for them? Counterproductive. Promises that technology will replace teachers? Repeatedly failed."}),(0,s.jsx)("p",{children:"Active learning environments that require genuine engagement. Assessment that tracks process and technique rather than just final answers. Technology that supports teachers rather than attempting to replace them. Platforms that make practical science accessible to schools that cannot afford or staff traditional laboratories. Tools that develop skills AI cannot fake."}),(0,s.jsx)("p",{children:"That is the educational technology worth investing in. We are trying to be a small part of building it."}),(0,s.jsx)("h2",{children:"Related Articles"}),(0,s.jsxs)("ul",{children:[(0,s.jsx)("li",{children:(0,s.jsx)("a",{href:"/blog/oecd-ai-learning-paradox-virtual-labs",children:"The OECD AI Learning Paradox: Why GenAI Fails Students (And How Virtual Labs Succeed)"})}),(0,s.jsx)("li",{children:(0,s.jsx)("a",{href:"/blog/ai-assessment-crisis-solution",children:"The AI Assessment Crisis Has a Solution"})}),(0,s.jsx)("li",{children:(0,s.jsx)("a",{href:"/blog/pearson-webinar-vr-assessment-ai-age",children:"Assessment in the Age of AI: Join Our Pearson Webinar"})})]}),(0,s.jsxs)("div",{className:"references-section",children:[(0,s.jsx)("h3",{children:"References"}),(0,s.jsxs)("ul",{className:"references-list",children:[(0,s.jsxs)("li",{children:["Freeman, S., Eddy, S. L., McDonough, M., Smith, M. K., Okoroafor, N., Jordt, H., & Wenderoth, M. P. (2014). Active learning increases student performance in science, engineering, and mathematics. ",(0,s.jsx)("em",{children:"Proceedings of the National Academy of Sciences, 111"}),"(23), 8410-8415."]}),(0,s.jsxs)("li",{children:["Grewenig, E., Lergetporer, P., Werner, K., Woessmann, L., & Zierow, L. (2021). COVID-19 and educational inequality: How school closures affect low- and high-achieving students. ",(0,s.jsx)("em",{children:"European Economic Review, 140"}),", 103920."]}),(0,s.jsxs)("li",{children:["Macedonia, M. (2019). Embodied learning: Why at school the mind needs the body. ",(0,s.jsx)("em",{children:"Frontiers in Psychology, 10"}),", 2098."]}),(0,s.jsxs)("li",{children:["OECD. (2026). ",(0,s.jsx)("em",{children:"OECD Digital Education Outlook 2026"}),". OECD Publishing."," ",(0,s.jsx)("a",{href:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html",target:"_blank",rel:"noopener noreferrer",children:"Link"})]}),(0,s.jsxs)("li",{children:["CoSN. (2026). ",(0,s.jsx)("em",{children:"2026 Driving K-12 Innovation Report"}),". Consortium for School Networking."," ",(0,s.jsx)("a",{href:"https://www.cosn.org/tools-and-resources/resource/2026-driving-k-12-innovation-report-hurdles-accelerators-tech-enablers/",target:"_blank",rel:"noopener noreferrer",children:"Link"})]}),(0,s.jsxs)("li",{children:["The Economist. (2026, February 12). Is education technology mostly useless? ",(0,s.jsx)("em",{children:"The Economist"}),"."," ",(0,s.jsx)("a",{href:"https://www.economist.com/letters/2026/02/12/is-education-technology-mostly-useless",target:"_blank",rel:"noopener noreferrer",children:"Link"})]}),(0,s.jsxs)("li",{children:["Bloomberg. (2026, February 11). Kids Spend Hours in School on Screens. And for What? ",(0,s.jsx)("em",{children:"Bloomberg Opinion"}),"."," ",(0,s.jsx)("a",{href:"https://www.bloomberg.com/opinion/articles/2026-02-11/education-technology-isn-t-teaching-us-children-more-effectively",target:"_blank",rel:"noopener noreferrer",children:"Link"})]}),(0,s.jsxs)("li",{children:["Wieman, C. E., & Perkins, K. K. (2006). A powerful tool for teaching science. ",(0,s.jsx)("em",{children:"Nature Physics, 2"}),"(5), 290-292."]})]})]})]})}}]);
